// Draft concepts A/B/C for a selected segment, generated by the Studio from the
// edit kit and the reference library (author "draft"). They make the workflow
// usable immediately; Claude replaces or refines them with the skill
// (edit_decisions.py propose -> author "claude"). The user's text is used as
// written; drafts only decide layout and design.
import type { Concept, CreativeSegment } from "../../src/kit/project";

const words = (t: string) => t.replace(/\s+/g, " ").trim().split(" ").filter(Boolean);
const numberIn = (t: string) => {
  const m = t.match(/(\$|€|£)?\s?(\d[\d,]*(?:\.\d+)?)\s?(%|k|K|m|M|x)?/);
  if (!m) return null;
  return { prefix: m[1] ?? "", value: parseFloat(m[2].replace(/,/g, "")), suffix: m[3] ?? "", raw: m[0] };
};

/** Lead-in words + key phrase (the last 1-3 words), capped for a 1080-wide caption. */
const splitKey = (t: string) => {
  const w = words(t);
  const keyLen = w.length <= 2 ? w.length : w.length <= 5 ? 2 : 3;
  const key = w.slice(-keyLen).join(" ").replace(/[.,!?;:]+$/, "");
  const lead = w.slice(0, -keyLen).slice(-5).join(" ");
  return { lead, key };
};

/** Up to n short chunks (split on commas / "and" / evenly). */
const chunks = (t: string, n: number) => {
  const byPunct = t.split(/,|;|\band\b|\bor\b/).map((s) => s.trim()).filter(Boolean);
  if (byPunct.length >= 2) return byPunct.slice(0, n).map((s) => words(s).slice(0, 5).join(" "));
  const w = words(t);
  const size = Math.ceil(w.length / Math.min(n, Math.max(1, Math.ceil(w.length / 4))));
  const out: string[] = [];
  for (let i = 0; i < w.length && out.length < n; i += size) out.push(w.slice(i, i + size).slice(0, 5).join(" "));
  return out;
};

const draft = (c: Omit<Concept, "author">): Concept => ({ ...c, author: "draft" });

export const draftConcepts = (seg: CreativeSegment): { A: Concept; B: Concept; C: Concept; recommend: "A" | "B" | "C" } => {
  const dur = seg.end - seg.start;
  const { lead, key } = splitKey(seg.text);
  const num = numberIn(seg.text);
  const at = (f: number) => +Math.min(dur * f, dur - 0.6).toFixed(2);

  if (seg.type === "text") {
    return {
      recommend: "A",
      A: draft({
        title: "Serif key phrase", system: "B", kind: "CaptionAccent", refs: ["TXT-001", "TXT-004"], family: "SERIF-ACCENT-CAPTION",
        description: `quiet sans lead-in${lead ? ` "${lead}"` : ""} + amber italic serif "${key}" under the chin`,
        motion: "word-by-word fade-rise, the key phrase lands with blur-to-sharp", sound: "one pop on the key phrase",
        props: { lines: [...(lead ? [{ text: lead, style: "sans", at: 0.05 }] : []), { text: key, style: "serif", at: at(0.25) }] },
      }),
      B: draft({
        title: "Script word between caps", system: "B", kind: "CaptionAccent", refs: ["TXT-009", "ONS-005"], family: "SERIF-ACCENT-CAPTION",
        description: `caps lead${lead ? ` "${lead.toUpperCase()}"` : ""} with the script word "${key}" interlocked, cream on footage`,
        motion: "caps settle, the script word lands", sound: "pop, or silence on an emotional line",
        props: { serifFont: "Instrument Serif", lines: [...(lead ? [{ text: lead.toUpperCase(), style: "tracked", at: 0.05 }] : []), { text: key, style: "script", at: at(0.25) }] },
      }),
      C: draft({
        title: "Typewriter caption", system: "B", kind: "KineticText", refs: ["TXT-010"], family: "KINETIC-TYPE",
        description: `your words type on letter by letter under the chin, "${key}" glows in the accent colour`,
        motion: "typewriter with a glowing cursor, quick blur-out", sound: "soft keyboard ticks",
        props: { text: seg.text, style: "typewriter", accent: [key], placement: "caption" },
      }),
    };
  }

  if (seg.sceneType === "halfscreen") {
    // no half-screen reference in the library yet: three layouts of the kit's HalfPanel, honestly without refs
    const words = seg.text.replace(/[.,!?;:]+$/, "").split(/\s+/);
    const headline = words.length <= 6 ? seg.text.replace(/[.,!?;:]+$/, "") : key;
    return {
      recommend: "A",
      A: draft({
        title: "Half panel: headline + accent", system: "A", kind: "HalfPanel", refs: [], family: "HALFSCREEN",
        description: `a dark panel fills the lower half with "${headline}" (accent on "${key}"); you stay visible above it`,
        motion: "panel slides up from the bottom edge, slides back down", sound: "soft whoosh on the slide",
        props: { headline, accent: key },
      }),
      B: draft({
        title: "Half panel: checklist", system: "A", kind: "HalfPanel", refs: [], family: "HALFSCREEN",
        description: `lower-half panel with your words as short check rows: ${chunks(seg.text, 3).map((c) => `"${c}"`).join(", ")}`,
        motion: "panel slides up, rows stagger in", sound: "whoosh + a UI tick per row",
        props: { headline: key, accent: key, rows: chunks(seg.text, 3), accentFont: "Montserrat" },
      }),
      C: draft({
        title: "Half panel: warm kicker", system: "A", kind: "HalfPanel", refs: [], family: "HALFSCREEN",
        description: `amber-accented lower half: small kicker${lead ? ` "${lead}"` : ""} over a big "${key}"`,
        motion: "panel slides up, headline settles", sound: "soft whoosh",
        props: { kicker: lead || undefined, headline: key, accent: key, accentColor: "#F2A14A", top: 0.52 },
      }),
    };
  }

  if (seg.type === "onscreen") {
    const parts = chunks(seg.text, 3);
    const stat: Concept = num
      ? draft({
          title: "Stat card", system: "A", kind: "StatCard", refs: ["ONS-024", "ONS-050"], family: "NEON-RIM",
          description: `glass stat card, curve draws to a glowing peak, ${num.raw.trim()} counts up (your number)`,
          motion: "card fade-rise, curve draws, count-up on the stressed word", sound: "sci-fi impact + whoosh on the curve",
          props: { label: words(seg.text.replace(num.raw, "")).slice(0, 5).join(" ") || "Result", value: num.value, prefix: num.prefix, suffix: num.suffix },
        })
      : draft({
          title: "Single highlighted chip", system: "A", kind: "UiCard", refs: ["ONS-001", "ONS-016"], family: "LIVE-UI",
          description: `one dark-glass chip "${key}" lights up blue beside you`,
          motion: "fade-rise, then the accent border lights", sound: "UI click + sci-fi click on the light",
          props: { variant: "rows", look: "glass", rows: [{ title: key, sub: lead || undefined }], active: 0, anchor: { x: 0.5, y: 0.72 } },
        });
    return {
      recommend: num ? "C" : "A",
      A: draft({
        title: "Glass card", system: "A", kind: "UiCard", refs: ["ONS-024", "ONS-001"], family: "GLASS-DARK",
        description: `a frosted-glass card with a blue rim light tilts in beside you; ${parts.length} rows light up one by one: ${parts.map((p) => `"${p}"`).join(", ")}`,
        motion: "3D tilt-in with blur to sharp, light sweep, rows stagger 120 ms apart, the first row glows", sound: "one UI click per row",
        props: { variant: "rows", look: "glass", rows: parts.map((p) => ({ title: p })), active: 0, stagger: 0.12 },
      }),
      B: draft({
        title: "Inbox cards", system: "A", kind: "UiCard", refs: ["ONS-003"], family: "LIVE-UI",
        description: "message cards stack in under an inbox header, like real product UI",
        motion: "header, then cards stagger in", sound: "UI click per card",
        props: { variant: "inbox", header: words(lead || key).slice(0, 3).join(" "), rows: parts.slice(0, 2).map((p, i) => ({ title: i === 0 ? key : p, sub: p })), anchor: { x: 0.55, y: 0.7 } },
      }),
      C: stat,
    };
  }

  if (seg.type === "fullscreen") {
    const w = words(seg.text);
    const third = Math.max(1, Math.ceil(w.length / 3));
    const lines = [w.slice(0, third), w.slice(third, 2 * third), w.slice(2 * third)].map((l) => l.join(" ")).filter(Boolean);
    const horizon: Concept | null = num
      ? draft({
          title: "Horizon number", system: "C", kind: "HorizonTitle", refs: ["FUL-002"], family: "HORIZON-ARC",
          description: `planet horizon rises, ${num.raw.trim()} counts up out of the atmosphere (your number)`,
          motion: "sunrise rise, count-up, slow push", sound: "riser + hit into the cut, classy airy whoosh on the rise",
          props: { kicker: words(seg.text.replace(num.raw, "")).slice(0, 4).join(" "), value: num.value, prefix: num.prefix, suffix: num.suffix, body: lead || undefined },
        })
      : null;
    return {
      recommend: "A",
      A: draft({
        title: "Aurora stacked headline", system: "C", kind: "StatementScene", refs: ["FUL-063"], family: "AURORA-GRADIENT",
        description: "your line as a mixed-weight stacked headline on a blue aurora; the middle line heavy",
        motion: "lines rise and de-blur in sequence, slow push", sound: "sci-fi entry on the cut, pop on the heavy line",
        props: { variant: "aurora", lines, accentLine: Math.min(1, lines.length - 1) },
      }),
      B: draft({
        title: "Glowing grid statement", system: "C", kind: "KineticText", refs: ["FUL-072", "FUL-063"], family: "KINETIC-TYPE",
        description: `your line rises word by word over a glowing perspective grid; a light bar sweeps behind "${key}"`,
        motion: "words rise out of blur, highlight sweep, slow zoom in", sound: "sci-fi entry on the cut, pop on the highlight",
        props: { text: seg.text, style: "highlight-sweep", accent: [key], placement: "fullscreen", background: "grid-floor" },
      }),
      C:
        horizon ??
        draft({
          title: "Light-streak statement", system: "C", kind: "StatementScene", refs: ["FUL-006", "FUL-012"], family: "LIGHT-STREAK",
          description: "black frame, two blue light streaks cross behind your line; cut on the flash",
          motion: "streaks accelerate in and cross, the line glows", sound: "transition whoosh on the streaks (fastest frame)",
          props: { variant: "streak", lines: lines.slice(0, 2), accentLine: 0 },
        }),
    };
  }

  // sound design concepts (System D): placements relative to the segment; sounds come from the user's library
  return {
    recommend: "A",
    A: draft({ title: "Build into the moment", system: "D", refs: [], description: "riser resolving on the segment start with an impact hit beneath (Joseph: anticipation)", sfx: [{ family: "riser", label: "riser resolves", at: "start", roles: ["sharp-bass-riser", "metallic-riser"] }, { family: "hit", label: "hit beneath", at: "start", roles: ["impact-hit"] }] }),
    B: draft({ title: "Texture accent", system: "D", refs: [], description: "one texture (pop / sci-fi click) on the segment start, nothing else", sfx: [{ family: "texture", label: "accent", at: "start", roles: ["pop", "sci-fi-click"] }] }),
    C: draft({ title: "Movement + landing", system: "D", refs: [], description: "a whoosh peaking on the start and a soft texture on the end", sfx: [{ family: "whoosh", label: "whoosh", at: "start", roles: ["hollow-whoosh", "deep-voice-whoosh"] }, { family: "texture", label: "landing", at: "end", roles: ["pop", "ui-click"] }] }),
  };
};
